<?php
if(!defined('ABSPATH'))exit;
/** TUFF BEATZ Studio File Manager V12.6 — explicit production categories */
function tuff_beatz_file_manager_categories(){return array('source'=>'Source Files','stems'=>'Stems','mixes'=>'Mix Versions','masters'=>'Masters','final'=>'Final Delivery');}
function tuff_beatz_file_manager_bucket($file){$explicit=sanitize_key($file['studio_category']??'');if(isset(tuff_beatz_file_manager_categories()[$explicit]))return $explicit;$cat=sanitize_key($file['category']??'source');$v=strtolower((string)($file['version']??''));$n=strtolower((string)($file['name']??''));if($cat==='delivery'){if(strpos($v,'final')!==false||strpos($v,'delivery')!==false||strpos($n,'final')!==false)return 'final';if(strpos($v,'master')!==false||strpos($n,'master')!==false)return 'masters';return 'mixes';}if(strpos($v,'stem')!==false||strpos($n,'stem')!==false)return 'stems';return 'source';}
function tuff_beatz_file_manager_label($bucket){$m=tuff_beatz_file_manager_categories();return $m[$bucket]??'Project Files';}
function tuff_beatz_file_manager_icon($name){$ext=strtolower(pathinfo($name,PATHINFO_EXTENSION));if(in_array($ext,array('wav','aiff','aif','mp3','m4a'),true))return '♫';if($ext==='zip')return 'ZIP';if($ext==='pdf')return 'PDF';if(in_array($ext,array('mid','midi'),true))return 'MIDI';return 'FILE';}
function tuff_beatz_file_manager_upload(){ $id=(int)($_POST['request_id']??0);$r=function_exists('tuff_beatz_project_dashboard_url')?tuff_beatz_project_dashboard_url($id).'#files':home_url('/project-dashboard/');if(!$id||!is_user_logged_in()||!function_exists('tuff_beatz_user_project_permission')||!tuff_beatz_user_project_permission($id,'upload')){wp_safe_redirect(home_url('/start-a-project/'));exit;}if(!isset($_POST['tb_fm_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['tb_fm_nonce'])),'tb_fm_upload_'.$id)){wp_safe_redirect($r);exit;}$studio=sanitize_key(wp_unslash($_POST['studio_category']??'source'));$cats=tuff_beatz_file_manager_categories();if(!isset($cats[$studio]))$studio='source';$version=sanitize_text_field(wp_unslash($_POST['upload_version']??''));if(!$version)$version=$cats[$studio];$vault_category=in_array($studio,array('mixes','masters','final'),true)?'delivery':'source';$new=function_exists('tuff_beatz_vault_save_files')?tuff_beatz_vault_save_files($id,'project_files',$vault_category,$version):array();if($new){$ids=array();foreach($new as $f)$ids[]=$f['id']??'';$all=tuff_beatz_vault_files($id);foreach($all as &$f){if(in_array($f['id']??'',$ids,true))$f['studio_category']=$studio;}unset($f);update_post_meta($id,'_tb_vault_files',$all);if($studio==='mixes'){if(function_exists('tuff_beatz_workflow_apply_status'))tuff_beatz_workflow_apply_status($id,'revision','Studio File Manager Mix Upload');}elseif($studio==='masters'){if(function_exists('tuff_beatz_workflow_apply_status'))tuff_beatz_workflow_apply_status($id,'mastering','Studio File Manager Master Upload');}elseif($studio==='final'){if(function_exists('tuff_beatz_workflow_apply_status'))tuff_beatz_workflow_apply_status($id,'delivery','Studio File Manager Final Delivery');}if(function_exists('tuff_beatz_add_activity'))tuff_beatz_add_activity($id,'file',count($new).' file(s) uploaded to '.$cats[$studio]);}wp_safe_redirect(add_query_arg(array('files_added'=>(string)count($new),'file_category'=>$studio),$r));exit;}
add_action('admin_post_tb_file_manager_upload','tuff_beatz_file_manager_upload');
function tuff_beatz_file_manager_render(){if(!is_page('project-dashboard')||!is_user_logged_in())return;$id=(int)($_GET['project']??0);if(!$id||!function_exists('tuff_beatz_user_project_permission')||!tuff_beatz_user_project_permission($id,'view'))return;$files=function_exists('tuff_beatz_vault_files')?tuff_beatz_vault_files($id):array();$groups=array('source'=>array(),'stems'=>array(),'mixes'=>array(),'masters'=>array(),'final'=>array());foreach($files as $f)$groups[tuff_beatz_file_manager_bucket($f)][]=$f;$can_upload=tuff_beatz_user_project_permission($id,'upload');echo '<template id="tb-file-manager-template"><section id="files" class="tb-portal-card tb-workspace-section tb-file-manager"><div class="tb-fm-head"><div><p class="tb-card-kicker">STUDIO FILE MANAGER</p><h2>Files & Versions</h2><p>Private project assets organized by explicit production category.</p></div><div class="tb-fm-total"><strong>'.esc_html(count($files)).'</strong><span>SECURE FILES</span></div></div><div class="tb-fm-tabs">';foreach($groups as $key=>$items)echo '<button type="button" data-fm-filter="'.esc_attr($key).'">'.esc_html(tuff_beatz_file_manager_label($key)).'<b>'.esc_html(count($items)).'</b></button>';echo '</div><div class="tb-fm-groups">';foreach($groups as $key=>$items){echo '<section class="tb-fm-group" data-fm-group="'.esc_attr($key).'"><div class="tb-fm-group-head"><div><small>'.esc_html(strtoupper($key)).'</small><h3>'.esc_html(tuff_beatz_file_manager_label($key)).'</h3></div><span>'.esc_html(count($items)).' item'.(count($items)===1?'':'s').'</span></div>';if(!$items){echo '<div class="tb-fm-empty">No '.esc_html(strtolower(tuff_beatz_file_manager_label($key))).' yet.</div>';}else{foreach(array_reverse($items) as $f){$u=(int)($f['uploaded_by']??0);$user=$u?get_userdata($u):null;$who=$user?$user->display_name:'TUFF BEATZ';$when=!empty($f['uploaded_at'])?mysql2date('M j, Y • g:i a',$f['uploaded_at']):'';$version=$f['version']?:'Project File';echo '<a class="tb-fm-file" href="'.esc_url(tuff_beatz_vault_download_url($id,$f['id'])).'"><span class="tb-fm-icon">'.esc_html(tuff_beatz_file_manager_icon($f['name']??'')).'</span><div class="tb-fm-file-main"><strong>'.esc_html($f['name']??'File').'</strong><span>'.esc_html($version).' • '.esc_html(tuff_beatz_vault_human_size($f['size']??0)).'</span></div><div class="tb-fm-meta"><small>UPLOADED BY</small><b>'.esc_html($who).'</b><span>'.esc_html($when).'</span></div><em>Download ↓</em></a>';}}echo '</section>';}echo '</div>';if($can_upload){echo '<form method="post" enctype="multipart/form-data" action="'.esc_url(admin_url('admin-post.php')).'" class="tb-fm-upload"><input type="hidden" name="action" value="tb_file_manager_upload"><input type="hidden" name="request_id" value="'.esc_attr($id).'">';wp_nonce_field('tb_fm_upload_'.$id,'tb_fm_nonce');echo '<div><small>ADD TO PRIVATE VAULT</small><h3>Upload Project Files</h3><p>Choose exactly where these files belong in the production workflow.</p></div><label class="tb-fm-field"><span>Category</span><select name="studio_category">';foreach(tuff_beatz_file_manager_categories() as $key=>$label)echo '<option value="'.esc_attr($key).'">'.esc_html($label).'</option>';echo '</select></label><label class="tb-fm-field"><span>Version</span><input name="upload_version" type="text" placeholder="Example: Vocal Stems V2"></label><label class="tb-fm-field tb-fm-filepick"><span>Files</span><input name="project_files[]" type="file" multiple accept=".wav,.aiff,.aif,.mp3,.m4a,.zip,.pdf,.txt,.mid,.midi"></label><button class="btn btn-gold" type="submit">Upload Securely</button></form>';}echo '</section></template><script>document.addEventListener("DOMContentLoaded",function(){var t=document.getElementById("tb-file-manager-template"),old=document.getElementById("files");if(t&&old){old.replaceWith(t.content.cloneNode(true));var root=document.getElementById("files"),buttons=root?root.querySelectorAll("[data-fm-filter]"):[];function show(key){root.querySelectorAll("[data-fm-group]").forEach(function(g){g.hidden=g.getAttribute("data-fm-group")!==key;});buttons.forEach(function(b){b.classList.toggle("is-active",b.getAttribute("data-fm-filter")===key);});}buttons.forEach(function(b){b.addEventListener("click",function(){show(b.getAttribute("data-fm-filter"));});});var first=Array.prototype.find.call(buttons,function(b){return parseInt((b.querySelector("b")||{}).textContent||"0",10)>0;})||buttons[0];if(first)show(first.getAttribute("data-fm-filter"));}});</script>';}
add_action('wp_footer','tuff_beatz_file_manager_render',5);
function tuff_beatz_file_manager_assets(){if(is_page('project-dashboard')){$p=get_template_directory().'/assets/css/file-manager.css';if(file_exists($p))wp_enqueue_style('tuff-beatz-file-manager',get_template_directory_uri().'/assets/css/file-manager.css',array('tuff-beatz-project-portal'),filemtime($p));}}
add_action('wp_enqueue_scripts','tuff_beatz_file_manager_assets',49);
